# Transfer the person to another sheet (by id). Anyone but a steward, a retired person, this sheet's own id, an
# archived sheet, or a name or alias already on another sheet of the other sheet's tree is refused (400); a person not
# on the sheet (404). The person arrives on the other sheet with their grades, terms, contact, aliases and claims
# (renumbered there; figures a statement bound and references lost) and leaves this sheet entirely. When someone on
# the other sheet has their name or one of their aliases as a name or alias, the arriving person is merged into them,
# as a merge does (refused when that is more than one person or a retired one); otherwise a contact already there is
# refused. Each sheet records the transfer (the other sheet then the merge), followed by its rollup.
archived:
  class: net.officefloor.hq.app.sheet.CheckNotArchived
  next: viewer
viewer:
  class: net.officefloor.hq.app.setting.CheckNotViewer
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateTransferRequest
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: check
check:
  class: net.officefloor.hq.app.person.CheckTransfer
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: target
target:
  class: net.officefloor.hq.app.person.SnapshotTransferTarget
  govern: [ transaction ]
  next: transfer
transfer:
  class: net.officefloor.hq.app.person.TransferPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonTransferred
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: arrived
arrived:
  class: net.officefloor.hq.app.person.AuditPersonArrived
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithTransfer
  govern: [ transaction ]
# Merge the person into another person on the sheet (by id). Anyone but a steward, the same person, or either of
# them retired is refused (400); a person not on the sheet (404). The merged person's claims, name, aliases, patrons
# and pool memberships pass to the other; their statements, holds, watchers and contact are dropped, and they leave
# the sheet.
archived:
  class: net.officefloor.hq.app.sheet.CheckNotArchived
  next: viewer
viewer:
  class: net.officefloor.hq.app.setting.CheckNotViewer
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateMergeRequest
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: check
check:
  class: net.officefloor.hq.app.person.CheckMerge
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: merge
merge:
  class: net.officefloor.hq.app.person.MergePerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonMerged
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithMerge
  govern: [ transaction ]
